use std::sync::LazyLock;

use crate::exercise::{Category, Equipment, ExerciseId, ExerciseInfo, MuscleGroup};
use crate::measure::MeasureKind;
use crate::text::NonEmptyText;

// Generated by build.rs from catalog.json: defines `RAW_CATALOG: &[RawBuiltin]`.
include!(concat!(env!("OUT_DIR"), "/catalog_data.rs"));

struct RawBuiltin {
    id: &'static str,
    name: &'static str,
    aliases: &'static [&'static str],
    category: Category,
    muscle_group: MuscleGroup,
    equipment: Equipment,
    measure: MeasureKind,
    retired: bool,
}

impl RawBuiltin {
    fn build(&self) -> Option<BuiltinExercise> {
        let name = NonEmptyText::new(self.name).ok()?;
        let info = ExerciseInfo::new(
            name,
            self.category,
            self.muscle_group,
            self.equipment,
            self.measure,
        )
        .ok()?;
        Some(BuiltinExercise {
            id: self.id,
            aliases: self.aliases,
            info,
            retired: self.retired,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BuiltinExercise {
    id: &'static str,
    aliases: &'static [&'static str],
    info: ExerciseInfo,
    retired: bool,
}

impl BuiltinExercise {
    pub const fn id(&self) -> &'static str {
        self.id
    }

    pub fn exercise_id(&self) -> ExerciseId {
        ExerciseId::Builtin(self.id.to_owned())
    }

    pub const fn aliases(&self) -> &'static [&'static str] {
        self.aliases
    }

    pub const fn info(&self) -> &ExerciseInfo {
        &self.info
    }

    // Pool ids are permanent: a retired exercise is no longer offered, but past sessions
    // that used it still load.
    pub const fn is_retired(&self) -> bool {
        self.retired
    }
}

// `filter_map` drops nothing in practice: build.rs rejects empty names and
// the `every_entry_is_valid` test checks category / measure combinations.
static CATALOG: LazyLock<Vec<BuiltinExercise>> =
    LazyLock::new(|| RAW_CATALOG.iter().filter_map(RawBuiltin::build).collect());

pub fn builtin_exercises() -> &'static [BuiltinExercise] {
    &CATALOG
}

pub fn builtin_exercise(id: &str) -> Option<&'static BuiltinExercise> {
    CATALOG.iter().find(|exercise| exercise.id == id)
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;

    use super::*;

    #[test]
    fn every_entry_is_valid() {
        for raw in RAW_CATALOG {
            assert!(raw.build().is_some(), "invalid entry: {}", raw.id);
        }
        assert_eq!(builtin_exercises().len(), RAW_CATALOG.len());
    }

    #[test]
    fn ids_are_unique() {
        let ids: BTreeSet<_> = builtin_exercises().iter().map(|e| e.id()).collect();
        assert_eq!(ids.len(), builtin_exercises().len());
    }

    #[test]
    fn names_are_unique_ignoring_case() {
        let names: BTreeSet<_> = builtin_exercises()
            .iter()
            .map(|e| e.info().name().as_str().to_lowercase())
            .collect();
        assert_eq!(names.len(), builtin_exercises().len());
    }

    #[test]
    fn every_measure_kind_is_represented() {
        let kinds: BTreeSet<_> = builtin_exercises()
            .iter()
            .map(|e| e.info().measure())
            .collect();
        assert_eq!(kinds.len(), 4);
    }

    #[test]
    fn finds_exercise_by_id() {
        let bench = builtin_exercise("barbell_bench_press").unwrap();
        assert_eq!(bench.info().name().as_str(), "Développé couché barre");
        assert_eq!(bench.info().measure(), MeasureKind::WeightReps);
        assert_eq!(
            bench.exercise_id(),
            ExerciseId::Builtin("barbell_bench_press".to_owned())
        );
        assert!(bench.aliases().contains(&"DC"));
        assert!(builtin_exercise("unknown").is_none());
        assert!(!bench.is_retired());
    }

    #[test]
    fn retired_exercises_stay_readable() {
        let roller = builtin_exercise("foam_roll_quads").unwrap();
        assert!(roller.is_retired());
        assert_eq!(
            roller.info().category(),
            crate::exercise::Category::Mobility
        );
    }
}
